1	// Acceptance test for the change request:
2	//   "Let me sort my clients by name. Or by how much they owe me."
3	//
4	// The clients list page (clients-page, /clients) gains ONE control (data-testid="client-sort")
5	// offering the two orderings the request names: by NAME, and by how much the client OWES. Choosing
6	// an ordering re-arranges the one client list (the client-row-<id> rows) into that order — it does
7	// not add, drop or duplicate clients, it only re-orders them.
8	//
9	// WHAT "OWES" MEANS. "How much they owe me" is the client's outstanding balance — exactly the figure
10	// the app already works out per client (client-statement.spec's client-outstanding-total): the sum,
11	// across all the client's invoices, of amount minus what has been paid, counting the invoices the
12	// user has actually sent (dashboard-owed-sent.spec: only SENT invoices are money owed). The seed
13	// below keeps this unambiguous: every invoice is SENT with no payments, so each client owes exactly
14	// its one invoice's amount — 100, 200 and 300 — regardless of how the roll-up handles drafts or
15	// part-payments.
16	//
17	// WHY THESE FIGURES. The three orderings are deliberately three DIFFERENT permutations of the rows,
18	// so the observed row order tells us unambiguously which key the list was sorted by and rules out the
19	// list having merely stayed in its default order:
20	//   - server/default order, by id   : [1, 2, 3]
21	//   - by name (alphabetical)         : [2, 1, 3]   (Acme, Beacon, Cobalt)
22	//   - by amount owed                 : [2, 3, 1]   (100, 200, 300)
23	// Because the request names no DIRECTION, a list is "sorted by name" when its rows run monotonically
24	// by name (A->Z or Z->A) and "sorted by owed" when they run monotonically by the owed amount
25	// (least-first or most-first); each test accepts either direction but pins the KEY — and since the
26	// name orderings, the owed orderings and the id order are all distinct, matching one proves the sort
27	// is keyed on that field and nothing else.
28	//
29	// THE CONTROL. One testid naming a two-way choice (by name / by owed) is a single native <select>
30	// with an option per ordering; the control owns a URL key so the chosen ordering outlives the click
31	// and a reload (CLAUDE.md rule 4, mirroring invoice-sort-due.spec). Options are matched by the
32	// MEANING of their text (/name/i, /owe|owing|outstanding|balance/i), not exact wording or position,
33	// so the test binds to the contract rather than to phrasing.
34	//
35	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
36	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and
37	// `invoices` honours { id, amount, projectId, status }. This change surfaces no audit records, so
38	// there is nothing to assert on the audit channel.
39	import { test, expect, type Page } from '@playwright/test';
40	import { resetAndSeed } from '../support/seed';
41	
42	// Three clients whose id order, name order and owed order are three different permutations (see the
43	// header). Each client has one project carrying one SENT, unpaid invoice, so the client owes exactly
44	// that invoice's amount.
45	const SEED = {
46	  clients: [
47	    { id: 1, name: 'Beacon Labs', email: 'hello@beacon.test' },
48	    { id: 2, name: 'Acme Corp', email: 'hello@acme.test' },
49	    { id: 3, name: 'Cobalt Studio', email: 'hello@cobalt.test' },
50	  ],
51	  projects: [
52	    { id: 1, name: 'Beacon Project', clientId: 1 },
53	    { id: 2, name: 'Acme Project', clientId: 2 },
54	    { id: 3, name: 'Cobalt Project', clientId: 3 },
55	  ],
56	  invoices: [
57	    { id: 1, amount: 300, projectId: 1, status: 'SENT' }, // Beacon (id 1) owes 300
58	    { id: 2, amount: 100, projectId: 2, status: 'SENT' }, // Acme   (id 2) owes 100
59	    { id: 3, amount: 200, projectId: 3, status: 'SENT' }, // Cobalt (id 3) owes 200
60	  ],
61	};
62	
63	const ID_ORDER = [1, 2, 3];
64	const NAME_ASC = [2, 1, 3]; // Acme, Beacon, Cobalt
65	const NAME_DESC = [3, 1, 2];
66	const OWED_ASC = [2, 3, 1]; // 100, 200, 300
67	const OWED_DESC = [1, 3, 2];
68	
69	const BY_NAME = /name/i;
70	const BY_OWED = /owe|owing|outstanding|balance/i;
71	
72	// The ids of the client rows in the order the DOM renders them (top to bottom).
73	async function rowOrder(page: Page): Promise<number[]> {
74	  return page
75	    .locator('[data-testid^="client-row-"]')
76	    .evaluateAll((els) =>
77	      els.map((el) => Number(el.getAttribute('data-testid')!.replace('client-row-', ''))),
78	    );
79	}
80	
81	// Choose an ordering on the client-sort control by the MEANING of its option text. The option's
82	// value is read from the live control (not assumed), so the test does not depend on the exact label
83	// wording or the order of the options.
84	async function sortBy(page: Page, meaning: RegExp): Promise<void> {
85	  const control = page.getByTestId('client-sort');
86	  await expect(control).toBeVisible();
87	  const options = await control
88	    .locator('option')
89	    .evaluateAll((opts) =>
90	      (opts as HTMLOptionElement[]).map((o) => ({ value: o.value, text: o.textContent ?? '' })),
91	    );
92	  const match = options.find((o) => meaning.test(o.text));
93	  if (!match) {
94	    throw new Error(`no client-sort option whose text matches ${meaning}; saw ${JSON.stringify(options)}`);
95	  }
96	  await control.selectOption(match.value);
97	}
98	
99	// Wait until the rows settle into one of the accepted orderings (the control writes to the URL and
100	// the list re-reads asynchronously), then return the order that matched for a clear failure message.
101	async function expectOrderOneOf(page: Page, accepted: number[][]): Promise<void> {
102	  const wanted = accepted.map((a) => a.join(','));
103	  await expect(async () => {
104	    const order = (await rowOrder(page)).join(',');
105	    expect(wanted).toContain(order);
106	  }).toPass();
107	}
108	
109	test.describe('Sort clients by name or by how much they owe', () => {
110	  test('the clients page offers a sort control over the one list', async ({ page }) => {
111	    await resetAndSeed(SEED);
112	
113	    await page.goto('/clients');
114	    await expect(page.getByTestId('clients-page')).toBeVisible();
115	
116	    // The new control is present, and all three clients are listed as their own rows.
117	    await expect(page.getByTestId('client-sort')).toBeVisible();
118	    await expect(page.locator('[data-testid^="client-row-"]')).toHaveCount(3);
119	  });
120	
121	  test('sorting by name arranges the clients alphabetically by name', async ({ page }) => {
122	    await resetAndSeed(SEED);
123	
124	    await page.goto('/clients');
125	    await expect(page.locator('[data-testid^="client-row-"]')).toHaveCount(3);
126	
127	    await sortBy(page, BY_NAME);
128	
129	    // Rows now run monotonically by name. Either direction counts, but the order must be a NAME
130	    // ordering — which is neither the id order nor an owed ordering, so this pins the key to name.
131	    await expectOrderOneOf(page, [NAME_ASC, NAME_DESC]);
132	
133	    // Sorting re-orders; it does not add, drop or duplicate clients.
134	    await expect(page.locator('[data-testid^="client-row-"]')).toHaveCount(3);
135	  });
136	
137	  test('sorting by how much they owe arranges the clients by their outstanding balance', async ({
138	    page,
139	  }) => {
140	    await resetAndSeed(SEED);
141	
142	    await page.goto('/clients');
143	    await expect(page.locator('[data-testid^="client-row-"]')).toHaveCount(3);
144	
145	    await sortBy(page, BY_OWED);
146	
147	    // Rows now run monotonically by the amount owed (100 / 200 / 300). Either direction counts, but
148	    // the order must be an OWED ordering — distinct from the id order and from either name ordering,
149	    // so a name sort or the default could not produce it: the sort is keyed on what the client owes.
150	    await expectOrderOneOf(page, [OWED_ASC, OWED_DESC]);
151	
152	    await expect(page.locator('[data-testid^="client-row-"]')).toHaveCount(3);
153	  });
154	
155	  test('switching between the two sorts re-arranges the same list each way', async ({ page }) => {
156	    await resetAndSeed(SEED);
157	
158	    await page.goto('/clients');
159	    await expect(page.locator('[data-testid^="client-row-"]')).toHaveCount(3);
160	
161	    // By name, then by owed: the one list follows the chosen key each time. Because a name ordering
162	    // and an owed ordering are different permutations, seeing each in turn proves the control truly
163	    // responds to the choice rather than leaving the rows in whatever order they already had.
164	    await sortBy(page, BY_NAME);
165	    await expectOrderOneOf(page, [NAME_ASC, NAME_DESC]);
