      projects: [
        { id: 1, name: 'Acme Project', clientId: 1 },
        { id: 2, name: 'Beacon Project', clientId: 2 },
      ],
      invoices: [
        { id: 1, amount: 300, projectId: 1, status: 'SENT' },
        { id: 2, amount: 200, projectId: 2, status: 'SENT' },
      ],
